import React,{useState,useEffect,useRef} from 'react';
import {createRoot} from 'react-dom/client';
import {LayoutDashboard,MapPin,Building2,ReceiptText,Users,Settings,LogOut,Plus,Search,ArrowUpRight,TrendingUp,Wallet,Check,Clock,AlertCircle,X,ChevronRight,ChevronDown,Download,Upload,SlidersHorizontal,Menu,LandPlot,CalendarDays,CheckCircle2,FileSpreadsheet,LoaderCircle,Pencil,Eye,ShieldCheck} from 'lucide-react';
import './style.css';
const cash=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(v||0));
const brdate=v=>v?new Date(v+'T12:00:00').toLocaleDateString('pt-BR'):'—';
const nowDate=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Cuiaba',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const today=nowDate();
const statusClient=s=>s.paidAt?'Pago':s.initialDue<today?'Atrasado':'Aguardando';
const statusParcel=p=>Math.round(p.received*100)>=Math.round(p.amount*100)?'Paga':p.due<today?'Atrasada':'Aguardando';
const total=s=>s.commissions.reduce((a,p)=>a+p.amount,0),received=s=>s.commissions.reduce((a,p)=>a+p.received,0);
const price=l=>l.condition==='Quitado'?l.price:l.balance==null?null:Number(l.premium)+Number(l.balance);
const initials=n=>n.split(' ').map(x=>x[0]).slice(0,2).join('');
async function api(action,data={},extra={}){const response=await fetch('/api/index',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,data,...extra})});const result=await response.json();if(!response.ok||result.error){const e=Error(result.error||'Não foi possível concluir.');e.status=response.status;throw e;}return result;}
const Badge=({children})=><span className={'badge '+(/pago|paga|assinado|disponível|concluída|liberado|ativo/i.test(children)&&!(/inativo|não liberado/i.test(children))?'green':/atras|cancelada|inativo/i.test(children)?'red':/reservado|aguardando/i.test(children)?'amber':'')}>{children}</span>;
const Empty=({text='Nenhum registro encontrado.'})=><div className="empty"><Search size={28}/><p>{text}</p><small>Revise os filtros ou cadastre um novo registro.</small></div>;
const Field=({label,children,wide=false})=><label className={'field '+(wide?'wide':'')}><span>{label}</span>{children}</label>;
function Modal({title,children,onClose,wide=false}){const ref=useRef();useEffect(()=>{const d=ref.current;d.showModal();return()=>d.close();},[]);return <dialog ref={ref} className={wide?'modal wide-modal':'modal'} onCancel={onClose} onClick={e=>{if(e.target===e.currentTarget)onClose();}}><header><div><span className="eyebrow">LOTEA / GESTÃO IMOBILIÁRIA</span><h2>{title}</h2></div><button className="icon-btn" aria-label="Fechar" onClick={onClose}><X/></button></header>{children}</dialog>;}
function App(){const [db,setDb]=useState(null),[loading,setLoading]=useState(true),[error,setError]=useState(''),[demo,setDemo]=useState(false),[page,setPage]=useState('Dashboard'),[modal,setModal]=useState(null),[toast,setToast]=useState(''),[mobile,setMobile]=useState(false),[busy,setBusy]=useState(false);
useEffect(()=>{api('state').then(setDb).catch(e=>{if(e.status!==401)setError(e.message);}).finally(()=>setLoading(false));api('info').then(r=>setDemo(r.demo)).catch(()=>{});},[]);
useEffect(()=>{if(toast){const t=setTimeout(()=>setToast(''),4500);return()=>clearTimeout(t);}},[toast]);
async function mutate(action,data,close=true){setBusy(true);try{const d=await api(action,data);setDb(d);if(close)setModal(null);setToast('Alterações salvas com sucesso.');return d;}finally{setBusy(false);}}
async function login(e,account){e?.preventDefault();setError('');setBusy(true);const f=e?Object.fromEntries(new FormData(e.currentTarget)):{};try{setDb(await api('login',{},account?{email:account,password:'LoteaDemo2026!'}:f));}catch(e){setError(e.message);}finally{setBusy(false);}}
if(loading)return <div className="loading"><LoaderCircle className="spin"/><p>Carregando seu espaço…</p></div>;
if(!db)return <div className="login"><div className="login-art"><Brand/><div><span className="eyebrow">GESTÃO IMOBILIÁRIA</span><h1>Mais clareza.<br/>Em cada negócio.</h1><p>Seu portfólio, suas vendas e suas comissões. Tudo no mesmo lugar.</p><div className="login-stats"><span><LandPlot/> Terrenos</span><span><ReceiptText/> Vendas</span><span><Wallet/> Comissões</span></div></div><small>Organização para quem constrói novos caminhos.</small></div><div className="login-form"><div className="login-mobile"><Brand/></div><span className="eyebrow">BEM-VINDO À LOTEA</span><h2>Acesse sua conta</h2><p className="muted">Entre para acompanhar seus negócios.</p><form onSubmit={login}><Field label="E-mail"><input type="email" name="email" autoComplete="username" required placeholder="seu@email.com"/></Field><Field label="Senha"><input name="password" type="password" autoComplete="current-password" required placeholder="Sua senha"/></Field>{error&&<p className="error">{error}</p>}<button className="primary" disabled={busy}>{busy?'Entrando…':'Entrar'}</button></form>{demo&&<div className="demo-login"><span className="eyebrow">EXPLORE COM DADOS FICTÍCIOS</span><button onClick={()=>login(null,'gestor@lotea.demo')} disabled={busy}><ShieldCheck size={17}/> Entrar como gestor</button><button onClick={()=>login(null,'corretor@lotea.demo')} disabled={busy}><Users size={17}/> Entrar como corretor</button></div>}</div></div>;
const manager=db.user.role==='Gestor';const nav=[['Dashboard',LayoutDashboard],['Terrenos de terceiros',LandPlot],['Produtos',Building2],['Minhas vendas',ReceiptText],...(manager?[['Todas as vendas',TrendingUp],['Usuários',Users],['Configurações',Settings]]:[])];
return <div className="app"><aside className={mobile?'sidebar mobile-open':'sidebar'}><Brand/><div className="workspace"><span className="workspace-icon">LI</span><div>Lotea Imobiliária<small>Seu espaço de negócios</small></div></div><span className="nav-label">PRINCIPAL</span><nav>{nav.map(([name,Icon],i)=><React.Fragment key={name}>{i===4&&<span className="nav-label admin-label">GESTÃO</span>}<button className={page===name?'active':''} onClick={()=>{setPage(name);setMobile(false);}}><Icon size={19}/>{name}{page===name&&<span className="nav-indicator"/>}</button></React.Fragment>)}</nav><div className="side-bottom">{db.demo&&<div className="demo-badge"><span/> Ambiente demonstrativo</div>}<div className="profile"><span className="avatar">{initials(db.user.name)}</span><div>{db.user.name}<small>{db.user.role}</small></div><button aria-label="Sair da conta" className="icon-btn" onClick={async()=>{await api('logout');setDb(null);setPage('Dashboard');}}><LogOut size={17}/></button></div></div></aside>{mobile&&<div className="mobile-scrim" onClick={()=>setMobile(false)}/>}
<div className="main"><header className="topbar"><div><button className="icon-btn mobile-toggle" aria-label="Abrir menu" onClick={()=>setMobile(!mobile)}><Menu/></button><span>Meu espaço</span><ChevronRight size={14}/><strong>{page}</strong></div><span className="today"><CalendarDays size={16}/>{new Date().toLocaleDateString('pt-BR',{day:'numeric',month:'long',year:'numeric'})}</span></header><main><div className="page-heading"><div><span className="eyebrow">{page==='Dashboard'?'VISÃO GERAL':'SEUS NEGÓCIOS, ORGANIZADOS'}</span><h1>{page==='Dashboard'?`Olá, ${db.user.name.split(' ')[0]}`:page}<span className="heading-dot">.</span></h1><p>{({Dashboard:'Acompanhe os resultados e o próximo passo de cada venda.','Terrenos de terceiros':'Encontre a oportunidade certa no seu portfólio.','Produtos':'Os empreendimentos que fazem parte da sua operação.','Minhas vendas':'Cada negociação e cada comissão, de perto.','Todas as vendas':'Uma visão completa dos negócios da equipe.',Usuários:'Pessoas e permissões da sua imobiliária.',Configurações:'Loteadoras, regras padrão e histórico da operação.'})[page]}</p></div>{(page==='Dashboard'||page.includes('vendas'))&&<button className="primary" onClick={()=>setModal({type:'sale'})}><Plus size={18}/>Registrar venda</button>}{page==='Produtos'&&manager&&<button className="primary" onClick={()=>setModal({type:'product'})}><Plus size={18}/>Adicionar produto</button>}{page==='Usuários'&&<button className="primary" onClick={()=>setModal({type:'user'})}><Plus size={18}/>Adicionar usuário</button>}</div>
{page==='Dashboard'&&<Dashboard db={db} open={setModal}/>}
{page==='Terrenos de terceiros'&&<Lands db={db} open={setModal} toast={setToast}/>}
{page==='Produtos'&&<Products db={db} open={setModal}/>}
{page.includes('vendas')&&<Sales db={db} mine={page==='Minhas vendas'} open={setModal}/>}
{page==='Usuários'&&<section className="panel"><div className="panel-head"><h2>Equipe</h2><span className="muted">{db.users.length} usuários</span></div><div className="table-scroll"><table><thead><tr><th>Nome</th><th>E-mail</th><th>Cargo</th><th>Situação</th><th/></tr></thead><tbody>{db.users.map(u=><tr key={u.id}><td><div className="person"><span className="avatar">{initials(u.name)}</span><strong>{u.name}</strong></div></td><td>{u.email}</td><td>{u.role}</td><td><Badge>{u.active?'Ativo':'Inativo'}</Badge></td><td><button className="icon-btn" aria-label={'Editar '+u.name} onClick={()=>setModal({type:'user',item:u})}><Pencil size={17}/></button></td></tr>)}</tbody></table></div></section>}
{page==='Configurações'&&<SettingsPage db={db} open={setModal}/>}
</main><footer className="footer">Lotea <span>Gestão imobiliária com clareza</span></footer></div>
{toast&&<div role="status" className="toast"><CheckCircle2 size={20}/>{toast}</div>}
{modal&&<Modal title={modalTitle(modal)} onClose={()=>setModal(null)} wide={['land','product','sale','landDetail','saleDetail','import'].includes(modal.type)}><ModalBody modal={modal} db={db} mutate={mutate} open={setModal} close={()=>setModal(null)} busy={busy}/></Modal>}
</div>;}
function Brand(){return <div className="brand"><span className="brand-icon"><LandPlot size={26}/></span>lotea<span className="brand-dot">.</span></div>;}
function PeriodFilters({filter,setFilter,db,extra=true}){const set=(k,v)=>setFilter({...filter,[k]:v});return <div className="filters"><label className="select-icon"><CalendarDays size={17}/><select aria-label="Período" value={filter.period} onChange={e=>set('period',e.target.value)}><option value="month">Este mês</option><option value="year">Este ano</option><option value="all">Todo o período</option><option value="custom">Personalizado</option></select></label>{filter.period==='month'&&<input aria-label="Mês" type="month" value={filter.month} onChange={e=>set('month',e.target.value)}/>}{filter.period==='year'&&<input aria-label="Ano" type="number" min="2000" max="2100" value={filter.year} onChange={e=>set('year',e.target.value)}/>} {filter.period==='custom'&&<><input aria-label="Data inicial" type="date" value={filter.start} onChange={e=>set('start',e.target.value)}/><span>até</span><input aria-label="Data final" type="date" value={filter.end} onChange={e=>set('end',e.target.value)}/></>}{extra&&<><select aria-label="Produto" value={filter.product||''} onChange={e=>set('product',e.target.value)}><option value="">Todos os produtos</option>{db.products.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select>{db.user.role==='Gestor'&&<><select aria-label="Corretor" value={filter.broker||''} onChange={e=>set('broker',e.target.value)}><option value="">Todos os corretores</option>{db.users.map(u=><option key={u.id} value={u.id}>{u.name}</option>)}</select><select aria-label="Loteadora" value={filter.developer||''} onChange={e=>set('developer',e.target.value)}><option value="">Todas as loteadoras</option>{db.developers.map(d=><option key={d.id} value={d.id}>{d.name}</option>)}</select></>}</> }</div>;}
const defaultPeriod=()=>({period:'month',month:today.slice(0,7),year:today.slice(0,4),start:today.slice(0,8)+'01',end:today,product:'',broker:'',developer:''});
function inPeriod(s,f,ignoreBroker=false){return (f.period==='all'||f.period==='month'&&s.date.slice(0,7)===f.month||f.period==='year'&&s.date.slice(0,4)===String(f.year)||f.period==='custom'&&s.date>=f.start&&s.date<=f.end)&&(!f.product||s.productId===f.product)&&(ignoreBroker||!f.broker||s.brokerId===f.broker)&&(!f.developer||s.developerId===f.developer);}
function Dashboard({db,open}){const [f,setF]=useState(defaultPeriod);const valid=db.sales.filter(s=>s.status!=='Cancelada'&&inPeriod(s,f)),signed=valid.filter(s=>s.contract==='Assinado'),vgv=signed.reduce((a,s)=>a+s.value,0),ps=valid.flatMap(s=>s.commissions),sum=(arr,k)=>arr.reduce((a,p)=>a+p[k],0),due=ps.filter(p=>statusParcel(p)==='Atrasada'),ranking=db.users.map(u=>({...u,count:db.rankingSales.filter(s=>s.brokerId===u.id&&inPeriod(s,f,true)).length,vgv:db.rankingSales.filter(s=>s.brokerId===u.id&&inPeriod(s,f,true)).reduce((a,s)=>a+s.value,0)})).filter(u=>u.count).sort((a,b)=>b.vgv-a.vgv),lateClient=valid.filter(s=>statusClient(s)==='Atrasado');
return <><PeriodFilters filter={f} setFilter={setF} db={db}/><div className="metrics"><Metric title="VGV vendido" value={cash(vgv)} sub={`${signed.length} contratos assinados`} icon={TrendingUp} featured/><Metric title="Vendas no período" value={signed.length.toString().padStart(2,'0')} sub={`${valid.filter(s=>s.contract!=='Assinado').length} aguardando assinatura`} icon={ReceiptText}/><Metric title="Comissões a receber" value={cash(sum(ps,'amount')-sum(ps,'received'))} sub="Saldo das vendas do período" icon={Wallet}/><Metric title="Comissões recebidas" value={cash(sum(ps,'received'))} sub="Recebido nas vendas do período" icon={CheckCircle2}/></div>
<div className="dashboard-grid"><section className="panel ranking"><div className="panel-head"><div><h2>Ranking da equipe</h2><p>VGV de contratos assinados</p></div><span className="mini-icon"><TrendingUp size={20}/></span></div>{!ranking.length?<Empty text="Nenhuma venda assinada neste período."/>:ranking.map((u,i)=><div className="ranking-row" key={u.id}><span className={'rank rank-'+i}>{String(i+1).padStart(2,'0')}</span><span className={'avatar color-'+i}>{initials(u.name)}</span><div className="rank-person"><strong>{u.name}</strong><div className="rank-bar"><i style={{width:(u.vgv/ranking[0].vgv*100)+'%'}}/></div><small>{u.count} {u.count===1?'venda':'vendas'}</small></div><strong className="rank-value">{cash(u.vgv)}</strong></div>)}<div className="panel-note">Vendas canceladas não entram no ranking.</div></section><section className="panel commission-summary"><div className="panel-head"><div><h2>Suas comissões{db.user.role==='Gestor'?' · equipe':''}</h2><p>Visão financeira das vendas selecionadas</p></div><Wallet size={20}/></div><div className="commission-total"><small>Total previsto</small><strong>{cash(sum(ps,'amount'))}</strong></div><div className="progress-track"><span style={{width:Math.min(100,sum(ps,'received')/(sum(ps,'amount')||1)*100)+'%'}}/></div><div className="commission-lines"><div><span><i className="dot green-dot"/>Recebidas</span><strong>{cash(sum(ps,'received'))}</strong></div><div><span><i className="dot blue-dot"/>A vencer</span><strong>{cash(ps.filter(p=>statusParcel(p)==='Aguardando').reduce((a,p)=>a+p.amount-p.received,0))}</strong></div><div><span><i className="dot red-dot"/>Vencidas</span><strong className="red-text">{cash(due.reduce((a,p)=>a+p.amount-p.received,0))}</strong></div></div></section></div>
{(lateClient.length>0||due.length>0)&&<div className="alert-strip"><span className="alert-symbol"><AlertCircle size={21}/></span><div><strong>Alguns pagamentos precisam de atenção</strong><p>{lateClient.length} pagamentos iniciais de clientes e {due.length} parcelas de comissão em atraso nas vendas do período.</p></div><button onClick={()=>open({type:'alerts',sales:valid})}>Ver pendências<ChevronRight size={17}/></button></div>}
<section className="panel"><div className="panel-head"><div><h2>Últimas vendas</h2><p>As negociações mais recentes do período</p></div><span className="muted">{valid.length} registros</span></div><SalesTable sales={[...valid].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5)} db={db} open={open} compact/></section></>;}
function Metric({title,value,sub,icon:Icon,featured}){return <article className={'metric '+(featured?'featured':'')}><div><span>{title}</span><Icon size={19}/></div><strong>{value}</strong><small>{featured&&<span className="tiny-check"><Check size={12}/></span>}{sub}</small></article>;}
function SalesTable({sales,db,open,compact=false}){if(!sales.length)return <Empty/>;return <div className="table-scroll"><table><thead><tr><th>Cliente / produto</th><th>Quadra · lote</th><th>Data da venda</th><th>Valor total</th><th>Contrato / cliente</th>{!compact&&<><th>Venda</th><th>Comissão total</th><th>Recebida / saldo</th></>}<th/></tr></thead><tbody>{sales.map(s=><tr key={s.id}><td><button className="text-btn cell-name" onClick={()=>open({type:'saleDetail',item:s})}>{s.client}</button><small>{s.productName}</small></td><td>Q{s.block} · L{s.lot}</td><td>{brdate(s.date)}</td><td className="strong">{cash(s.value)}</td><td><div className="stack-badges"><Badge>{s.contract}</Badge><Badge>{statusClient(s)}</Badge></div></td>{!compact&&<><td><Badge>{s.status}</Badge></td><td>{cash(total(s))}</td><td>{cash(received(s))}<small>Saldo {cash(total(s)-received(s))}</small></td></>}<td><button className="icon-btn" aria-label={'Detalhes de '+s.client} onClick={()=>open({type:'saleDetail',item:s})}><ChevronRight size={18}/></button></td></tr>)}</tbody></table></div>;}
function Sales({db,mine,open}){const [f,setF]=useState({...defaultPeriod(),period:'all'}),[q,setQ]=useState(''),[status,setStatus]=useState(''),[commission,setCommission]=useState('');let sales=db.sales.filter(s=>(!mine||s.brokerId===db.user.id)&&inPeriod(s,f)&&(!status||s.status===status)&&(!q||[s.client,s.productName,s.block,s.lot].join(' ').toLowerCase().includes(q.toLowerCase()))&&(!commission||s.commissions.some(p=>statusParcel(p)===commission)));return <><PeriodFilters filter={f} setFilter={setF} db={db}/><div className="filters"><label className="search-input"><Search size={17}/><input placeholder="Buscar cliente, produto ou lote…" value={q} onChange={e=>setQ(e.target.value)}/></label><select aria-label="Situação da venda" value={status} onChange={e=>setStatus(e.target.value)}><option value="">Todas as situações</option>{['Em andamento','Concluída','Cancelada'].map(x=><option key={x}>{x}</option>)}</select><select aria-label="Situação da comissão" value={commission} onChange={e=>setCommission(e.target.value)}><option value="">Todas as comissões</option>{['Aguardando','Paga','Atrasada'].map(x=><option key={x}>{x}</option>)}</select></div><section className="panel"><div className="panel-head"><h2>Vendas <span className="count">{sales.length}</span></h2><span className="muted">VGV assinado: {cash(sales.filter(s=>s.status!=='Cancelada'&&s.contract==='Assinado').reduce((a,s)=>a+s.value,0))}</span></div><SalesTable sales={sales} db={db} open={open}/></section></>;}
function modalTitle(m){return ({sale:'Registrar venda',land:'Adicionar terreno',product:'Adicionar produto',user:'Usuário',saleDetail:'Detalhes da venda',landDetail:'Detalhes do terreno',import:'Importar Excel',alerts:'Pagamentos em atraso',developer:'Loteadora',productDetail:'Detalhes do produto'})[m.type]||'Detalhes';}
createRoot(document.getElementById('root')).render(<App/>);

function Cover({photos=[],kind='land',label=''}){return photos[0]?<img className="cover-image" src={photos[0]} alt={label}/>:<div className={'cover-placeholder '+kind}><LandPlot size={34} strokeWidth={1}/><span>{kind==='product'?'EMPREENDIMENTO':'TERRENO'}</span><small>Foto não cadastrada</small></div>;}
function Lands({db,open,toast}){const [f,setF]=useState({q:'',neighborhood:'',condition:'',availability:'',minArea:'',maxArea:'',minPrice:'',maxPrice:'',minM2:'',maxM2:''}),[advanced,setAdvanced]=useState(false),[exporting,setExporting]=useState(false);const set=(k,v)=>setF({...f,[k]:v});const lands=db.lands.filter(l=>{const p=price(l),m=p===null?null:p/l.area;return (!f.q||[l.neighborhood,l.block,l.lot,l.address].join(' ').toLowerCase().includes(f.q.toLowerCase()))&&(!f.neighborhood||l.neighborhood===f.neighborhood)&&(!f.condition||f.condition===l.condition)&&(!f.availability||f.availability===l.availability)&&(!f.minArea||l.area>=+f.minArea)&&(!f.maxArea||l.area<=+f.maxArea)&&(!f.minPrice||p!==null&&p>=+f.minPrice)&&(!f.maxPrice||p!==null&&p<=+f.maxPrice)&&(!f.minM2||m!==null&&m>=+f.minM2)&&(!f.maxM2||m!==null&&m<=+f.maxM2);});return <><div className="portfolio-toolbar"><div className="portfolio-count"><strong>{lands.length}</strong> terrenos no portfólio</div><div className="actions"><button disabled={exporting} onClick={async()=>{setExporting(true);try{await exportLands(db.lands,db);toast('Planilha de todos os terrenos exportada.');}catch(e){toast('Não foi possível exportar: '+e.message);}finally{setExporting(false);}}}><Download size={16}/>{exporting?'Exportando…':'Exportar Excel'}</button><button onClick={()=>downloadJSON(db.lands)}><Download size={16}/>Backup completo</button><button onClick={()=>open({type:'import'})}><Upload size={16}/>Importar Excel</button><button className="primary" onClick={()=>open({type:'land'})}><Plus size={17}/>Adicionar terreno</button></div></div><div className="filters"><label className="search-input"><Search size={17}/><input placeholder="Buscar bairro, quadra ou lote…" value={f.q} onChange={e=>set('q',e.target.value)}/></label><select aria-label="Bairro" value={f.neighborhood} onChange={e=>set('neighborhood',e.target.value)}><option value="">Todos os bairros</option>{[...new Set(db.lands.map(l=>l.neighborhood))].sort().map(x=><option key={x}>{x}</option>)}</select><select aria-label="Condição" value={f.condition} onChange={e=>set('condition',e.target.value)}><option value="">Todas as condições</option><option>Quitado</option><option>Ágio</option></select><select aria-label="Disponibilidade" value={f.availability} onChange={e=>set('availability',e.target.value)}><option value="">Todas as disponibilidades</option>{['Disponível','Reservado','Vendido','Inativo'].map(x=><option key={x}>{x}</option>)}</select><button onClick={()=>setAdvanced(!advanced)}><SlidersHorizontal size={16}/>Faixas</button></div>{advanced&&<div className="range-filters">{[['minArea','Área mínima (m²)'],['maxArea','Área máxima (m²)'],['minPrice','Preço mínimo (R$)'],['maxPrice','Preço máximo (R$)'],['minM2','R$/m² mínimo'],['maxM2','R$/m² máximo']].map(([k,l])=><Field key={k} label={l}><input type="number" min="0" value={f[k]} onChange={e=>set(k,e.target.value)}/></Field>)}<button onClick={()=>setF({q:'',neighborhood:'',condition:'',availability:'',minArea:'',maxArea:'',minPrice:'',maxPrice:'',minM2:'',maxM2:''})}>Limpar filtros</button></div>}{!lands.length?<Empty/>:<div className="card-grid">{lands.map(l=><article className="property-card" key={l.id}><button className="card-cover-button" aria-label={'Abrir '+l.neighborhood+' quadra '+l.block+' lote '+l.lot} onClick={()=>open({type:'landDetail',item:l})}><Cover photos={l.photos} label={l.neighborhood}/><div className="cover-badge"><Badge>{l.availability}</Badge></div></button><div className="card-body"><span className="card-location"><MapPin size={13}/> {l.address||l.neighborhood}</span><button className="text-btn" onClick={()=>open({type:'landDetail',item:l})}><h3>{l.neighborhood}</h3></button><div className="lot-meta"><span>Quadra {l.block} · Lote {l.lot}</span><span>{l.area.toLocaleString('pt-BR')} m²</span></div><div className="card-price"><div><small>{l.condition==='Ágio'?'Valor do ágio':'Valor anunciado'}</small><strong>{cash(l.condition==='Ágio'?l.premium:l.price)}</strong></div><Badge>{l.condition}</Badge></div>{l.condition==='Ágio'&&<p className="balance-note">Saldo devedor: {l.balance==null?'não informado':cash(l.balance)}</p>}<div className="card-bottom"><span>{price(l)==null?'Preço por m² indisponível':cash(price(l)/l.area)+'/m²'+(l.condition==='Ágio'?' · estimado':'')}</span><button className="icon-btn" aria-label="Ver detalhes" onClick={()=>open({type:'landDetail',item:l})}><ArrowUpRight size={18}/></button></div></div></article>)}</div>}</>;}
function Products({db,open}){const [q,setQ]=useState(''),[state,setState]=useState('');const products=db.products.filter(p=>p.name.toLowerCase().includes(q.toLowerCase())&&(!state||String(p.active)===state));return <><div className="filters"><label className="search-input"><Search size={17}/><input placeholder="Buscar empreendimento…" value={q} onChange={e=>setQ(e.target.value)}/></label><select aria-label="Situação comercial" value={state} onChange={e=>setState(e.target.value)}><option value="">Todos os produtos</option><option value="true">Ativos</option><option value="false">Inativos</option></select><span className="muted">{products.length} empreendimentos</span></div><div className="card-grid">{products.map(p=><article className="property-card" key={p.id}><button className="card-cover-button" onClick={()=>open({type:'productDetail',item:p})} aria-label={'Abrir '+p.name}><Cover photos={p.photos} kind="product" label={p.name}/><div className="cover-badge"><Badge>{p.launch?'Lançamento':p.active?'Ativo':'Inativo'}</Badge></div></button><div className="card-body"><span className="card-location"><MapPin size={13}/>{p.location}</span><button className="text-btn" onClick={()=>open({type:'productDetail',item:p})}><h3>{p.name}</h3></button><p className="developer-label">{db.developers.find(d=>d.id===p.developerId)?.name}</p><p className="card-description">{p.description}</p><div className="card-bottom"><Badge>{p.construction?'Construção liberada':'Não liberado'}</Badge><button className="icon-btn" aria-label={'Detalhes de '+p.name} onClick={()=>open({type:'productDetail',item:p})}><ArrowUpRight size={18}/></button></div></div></article>)}</div>{!products.length&&<Empty/>}</>;}
function SettingsPage({db,open}){return <><section className="panel"><div className="panel-head"><div><h2>Loteadoras parceiras</h2><p>Regras padrão aplicadas ao cadastrar novos produtos.</p></div><button className="primary" onClick={()=>open({type:'developer'})}><Plus size={16}/>Adicionar loteadora</button></div><div className="table-scroll"><table><thead><tr><th>Loteadora</th><th>Contato</th><th>Comissão</th><th>Parcelas</th><th>Dia de pagamento</th><th/></tr></thead><tbody>{db.developers.map(d=><tr key={d.id}><td className="strong">{d.name}</td><td>{d.contact}</td><td>{d.percent}%</td><td>{d.installments}</td><td>Dia {d.payDay}</td><td><button className="icon-btn" aria-label={'Editar '+d.name} onClick={()=>open({type:'developer',item:d})}><Pencil size={16}/></button></td></tr>)}</tbody></table></div>{!db.developers.length&&<Empty/>}</section><section className="panel spaced"><div className="panel-head"><h2>Histórico da operação</h2><span className="muted">Autor, data e alterações</span></div><div className="audit-wrap"><Timeline items={db.audit}/></div></section></>;}
function FormShell({initial,onSave,children,submit='Salvar',onCancel,busy}){const [v,setV]=useState(initial),[error,setError]=useState('');const set=(k,val)=>setV(x=>({...x,[k]:val}));return <form className="form-shell" onSubmit={async e=>{e.preventDefault();setError('');try{await onSave(v);}catch(e){setError(e.message);}}}><div className="form-content">{children(v,set,setV)}{error&&<p role="alert" className="error wide">{error}</p>}</div><div className="form-footer"><button type="button" onClick={onCancel}>Cancelar</button><button className="primary" disabled={busy} type="submit">{busy?<><LoaderCircle className="spin" size={16}/>Salvando…</>:submit}</button></div></form>;}
function Input({v,set,name,label,type='text',required=false,min,max,step,wide=false,placeholder}){return <Field label={label+(required?' *':'')} wide={wide}><input name={name} type={type} value={v[name]??''} onChange={e=>set(name,e.target.value)} required={required} min={min} max={max} step={step||(type==='number'?'0.01':undefined)} placeholder={placeholder}/></Field>;}
function Select({v,set,name,label,options,required=false,wide=false}){return <Field label={label+(required?' *':'')} wide={wide}><select value={v[name]??''} onChange={e=>set(name,e.target.value)} required={required}>{options.map(o=>typeof o==='string'?<option key={o} value={o}>{o}</option>:<option key={o.value} value={o.value}>{o.label}</option>)}</select></Field>;}
function Textarea({v,set,name,label}){return <Field label={label} wide><textarea value={v[name]||''} onChange={e=>set(name,e.target.value)}/></Field>;}
function CheckBox({v,set,name,label}){return <label className="checkbox"><input type="checkbox" checked={!!v[name]} onChange={e=>set(name,e.target.checked)}/>{label}</label>;}
function RuleFields({v,set}){return <><Input v={v} set={set} name="percent" label="Comissão do corretor (%)" type="number" min="0" max="100" required/><Input v={v} set={set} name="installments" label="Quantidade de parcelas" type="number" min="1" max="120" step="1" required/><Input v={v} set={set} name="payDay" label="Dia de pagamento" type="number" min="1" max="31" step="1" required/></>;}
function Photos({v,set}){const [err,setErr]=useState(''),[loading,setLoading]=useState(false);return <div className="wide photo-field"><span>Fotos (até 5)</span><div className="photo-previews">{(v.photos||[]).map((s,i)=><div key={i}><img src={s} alt={'Foto '+(i+1)}/><button type="button" aria-label={'Remover foto '+(i+1)} onClick={()=>set('photos',v.photos.filter((_,j)=>j!==i))}><X size={13}/></button></div>)}</div><input aria-label="Adicionar fotos" type="file" accept="image/jpeg,image/png,image/webp" multiple disabled={loading} onChange={async e=>{setErr('');setLoading(true);try{const files=[...e.target.files];if(files.length+(v.photos?.length||0)>5)throw Error('Selecione no máximo cinco fotos.');const photos=await Promise.all(files.map(async file=>{if(file.size>15000000)throw Error('Cada foto deve ter até 15 MB.');const bitmap=await createImageBitmap(file);const canvas=document.createElement('canvas'),ratio=Math.min(1,1400/Math.max(bitmap.width,bitmap.height));canvas.width=bitmap.width*ratio;canvas.height=bitmap.height*ratio;canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const data=canvas.toDataURL('image/jpeg',.76);if(data.length>650000)throw Error('Esta foto ficou muito grande. Escolha uma imagem menor.');return data;}));set('photos',[...(v.photos||[]),...photos]);}catch(e){setErr(e.message);}finally{setLoading(false);e.target.value='';}}}/><small>{loading?'Processando fotos…':'A primeira foto será a capa. As imagens são reduzidas para manter o aplicativo leve.'}</small>{err&&<p className="error">{err}</p>}</div>;}
function LandForm({item,db,mutate,close,busy}){const initial=item||{neighborhood:'',block:'',lot:'',area:'',condition:'Quitado',price:'',premium:'',balance:'',balanceDate:'',owner:'',contact:'',address:'',description:'',notes:'',paymentTerms:'',paymentOptions:[],brokerId:db.user.id,availability:'Disponível',photos:[]};return <FormShell initial={initial} onSave={v=>mutate('land.save',v)} onCancel={close} busy={busy}>{(v,set)=><><h3 className="form-section">Identificação do terreno</h3><Input v={v} set={set} name="neighborhood" label="Bairro" required/><Input v={v} set={set} name="area" label="Área (m²)" type="number" min="0.01" required/><Input v={v} set={set} name="block" label="Quadra" required/><Input v={v} set={set} name="lot" label="Lote" required/><Input v={v} set={set} name="address" label="Localização / endereço" wide/><Select v={v} set={set} name="condition" label="Condição" options={['Quitado','Ágio']}/><Select v={v} set={set} name="availability" label="Disponibilidade" options={['Disponível','Reservado','Vendido','Inativo']}/><h3 className="form-section">Valores e condições</h3>{v.condition==='Quitado'?<Input v={v} set={set} name="price" label="Valor total pedido (R$)" type="number" min="0.01" required/>:<><Input v={v} set={set} name="premium" label="Valor do ágio (R$)" type="number" min="0" required/><Input v={v} set={set} name="balance" label="Saldo devedor informado (R$)" type="number" min="0"/><Input v={v} set={set} name="balanceDate" label="Data de referência do saldo" type="date" required={v.balance!==''&&v.balance!=null}/></>}<div className="calculation wide"><span>{v.condition==='Ágio'?'Valor total de referência (estimado)':'Preço por m²'}</span><strong>{v.condition==='Ágio'?(v.balance!==''&&v.balance!=null?cash(+v.premium+(+v.balance)):'Informe o saldo devedor para calcular'):(+v.area>0?cash(+v.price/+v.area)+'/m²':'Informe a área')}</strong></div><div className="wide"><span className="field-label">Formas de pagamento aceitas</span><div className="checkbox-row">{['Entrada','Parcelamento','Financiamento','Permuta'].map(x=><label className="checkbox" key={x}><input type="checkbox" checked={v.paymentOptions.includes(x)} onChange={e=>set('paymentOptions',e.target.checked?[...v.paymentOptions,x]:v.paymentOptions.filter(o=>o!==x))}/>{x}</label>)}</div></div><Textarea v={v} set={set} name="paymentTerms" label="Detalhes das condições de pagamento"/><h3 className="form-section">Proprietário e responsável</h3><Input v={v} set={set} name="owner" label="Nome do proprietário" required/><Input v={v} set={set} name="contact" label="Contato do proprietário" required/>{db.user.role==='Gestor'&&<Select v={v} set={set} name="brokerId" label="Corretor responsável" options={db.users.filter(u=>u.active).map(u=>({value:u.id,label:u.name}))}/>}<Textarea v={v} set={set} name="description" label="Descrição"/><Textarea v={v} set={set} name="notes" label="Observações"/><Photos v={v} set={set}/></>}</FormShell>;}
function DeveloperFields({v,set}){return <><Input v={v} set={set} name="name" label="Nome da loteadora" required/><Input v={v} set={set} name="contact" label="Contato" required/><h3 className="form-section">Regras padrão de comissão</h3><RuleFields v={v} set={set}/><p className="form-help wide">As regras serão sugeridas ao cadastrar um produto. Alterações não modificam produtos ou vendas já cadastrados.</p></>;}
function ProductForm({item,db,mutate,close,busy}){const [adding,setAdding]=useState(false),[dev,setDev]=useState({name:'',contact:'',percent:3,installments:3,payDay:20}),[err,setErr]=useState('');return <FormShell initial={item||{name:'',developerId:'',location:'',mapUrl:'',description:'',photos:[],launch:false,construction:false,active:true,percent:3,installments:3,payDay:20}} onSave={v=>mutate('product.save',v)} onCancel={close} busy={busy}>{(v,set,setV)=><><Input v={v} set={set} name="name" label="Nome do empreendimento" required wide/><Field label="Loteadora *"><select value={v.developerId} required onChange={e=>{const d=db.developers.find(x=>x.id===e.target.value);setV(x=>({...x,developerId:e.target.value,...(d?{percent:d.percent,installments:d.installments,payDay:d.payDay}:{})}));}}><option value="">Selecione</option>{db.developers.map(d=><option key={d.id} value={d.id}>{d.name}</option>)}</select></Field><div className="align-end"><button type="button" onClick={()=>setAdding(!adding)}><Plus size={16}/>Cadastrar loteadora</button></div>{adding&&<div className="inline-form wide"><h3>Nova loteadora</h3><div className="form-grid"><DeveloperFields v={dev} set={(k,val)=>setDev({...dev,[k]:val})}/></div>{err&&<p className="error">{err}</p>}<button type="button" disabled={busy} onClick={async()=>{setErr('');try{const result=await mutate('developer.save',dev,false);const d=result.developers.at(-1);setV(x=>({...x,developerId:d.id,percent:d.percent,installments:d.installments,payDay:d.payDay}));setAdding(false);}catch(e){setErr(e.message);}}}>Salvar loteadora</button></div>}<Input v={v} set={set} name="location" label="Localização" required/><Input v={v} set={set} name="mapUrl" label="Link do mapa" type="url"/><Textarea v={v} set={set} name="description" label="Descrição breve"/><div className="checkbox-row wide"><CheckBox v={v} set={set} name="launch" label="Lançamento"/><CheckBox v={v} set={set} name="construction" label="Liberado para construção"/><CheckBox v={v} set={set} name="active" label="Produto ativo"/></div><h3 className="form-section">Regras deste produto</h3><RuleFields v={v} set={set}/><p className="form-help wide">Você pode definir exceções às regras da loteadora. Vendas existentes preservam as regras originais.</p><Photos v={v} set={set}/></>}</FormShell>;}
function SaleForm({db,mutate,close,busy}){return <FormShell initial={{client:'',contact:'',productId:'',block:'',lot:'',brokerId:db.user.id,date:today,value:'',contract:'Aguardando assinatura',signedAt:'',initial:'',initialDue:today,paidAt:'',notes:''}} onSave={v=>mutate('sale.create',v)} onCancel={close} busy={busy} submit="Registrar venda">{(v,set)=>{const p=db.products.find(p=>p.id===v.productId);return <><h3 className="form-section">Cliente e imóvel</h3><Input v={v} set={set} name="client" label="Nome do cliente" required/><Input v={v} set={set} name="contact" label="Contato" required/><Select v={v} set={set} name="productId" label="Produto" required options={[{value:'',label:'Selecione um produto'},...db.products.filter(p=>p.active).map(p=>({value:p.id,label:p.name}))]}/>{db.user.role==='Gestor'?<Select v={v} set={set} name="brokerId" label="Corretor responsável" options={db.users.filter(u=>u.active).map(u=>({value:u.id,label:u.name}))}/>:<Field label="Corretor responsável"><input value={db.user.name} disabled/></Field>}<Input v={v} set={set} name="block" label="Quadra" required/><Input v={v} set={set} name="lot" label="Lote" required/><Input v={v} set={set} name="date" label="Data da venda" type="date" max={today} required/><Input v={v} set={set} name="value" label="Valor total do lote (VGV) — R$" type="number" min="0.01" required/><h3 className="form-section">Contrato e pagamento inicial</h3><Select v={v} set={set} name="contract" label="Situação do contrato" options={['Aguardando assinatura','Assinado']}/>{v.contract==='Assinado'&&<Input v={v} set={set} name="signedAt" label="Data da assinatura" type="date" max={today} required/>}<Input v={v} set={set} name="initial" label="Pagamento inicial do cliente (R$)" type="number" min="0" max={v.value||undefined} required/><Input v={v} set={set} name="initialDue" label="Vencimento combinado" type="date" required/><Input v={v} set={set} name="paidAt" label="Data do pagamento efetivo (se pago)" type="date" max={today}/><h3 className="form-section">Comissão do corretor</h3>{p?<div className="sale-rule-preview wide"><div><small>Loteadora</small><strong>{db.developers.find(d=>d.id===p.developerId)?.name}</strong></div><div><small>Regra do produto</small><strong>{p.percent}% em {p.installments} parcelas · dia {p.payDay}</strong></div><div><small>Comissão total</small><strong>{cash(+v.value*p.percent/100)}</strong></div><p>A primeira parcela vence no mês seguinte à venda. O calendário não muda com atrasos do cliente.</p></div>:<p className="form-help wide">Selecione um produto para carregar as regras de comissão.</p>}<Textarea v={v} set={set} name="notes" label="Observações"/></>;}}</FormShell>;}
function UserForm({item,mutate,close,busy}){return <FormShell initial={item?{...item,password:''}:{name:'',email:'',password:'',role:'Corretor',active:true}} onSave={v=>mutate('user.save',v)} onCancel={close} busy={busy}>{(v,set)=><><Input v={v} set={set} name="name" label="Nome completo" required/><Input v={v} set={set} name="email" label="E-mail" type="email" required/><Input v={v} set={set} name="password" label={item?'Nova senha (deixe vazio para manter)':'Senha (mínimo 12 caracteres)'} type="password" required={!item}/><Select v={v} set={set} name="role" label="Cargo" options={['Corretor','Gestor']}/><CheckBox v={v} set={set} name="active" label="Usuário ativo"/><p className="form-help wide">Gestores podem gerenciar a equipe, confirmar comissões e cancelar vendas. Corretores acessam apenas os detalhes de suas próprias vendas.</p></>}</FormShell>;}
function Timeline({items}){return !items?.length?<p className="muted">Nenhuma atividade registrada.</p>:<div className="timeline">{items.map(h=><div className="timeline-event" key={h.id}><span className="timeline-point"/><div><div className="timeline-heading"><strong>{h.action}</strong><time>{new Date(h.at).toLocaleString('pt-BR',{timeZone:'America/Cuiaba'})}</time></div><small>{h.author}</small>{h.details&&<p>{h.details}</p>}</div></div>)}</div>;}
function DetailGrid({entries}){return <dl className="detail-grid">{entries.map(([label,value])=><div key={label}><dt>{label}</dt><dd>{value??'—'}</dd></div>)}</dl>;}
function LandDetail({item,db,open,mutate,busy}){const l=db.lands.find(l=>l.id===item.id),[activity,setActivity]=useState(''),[error,setError]=useState('');return <div className="detail-content"><div className="detail-title"><div><h2>{l.neighborhood}</h2><p>Quadra {l.block} · Lote {l.lot} · {l.area} m²</p></div><div className="actions"><Badge>{l.availability}</Badge>{(db.user.role==='Gestor'||db.user.id===l.brokerId)&&<button onClick={()=>open({type:'land',item:l})}><Pencil size={15}/>Editar</button>}</div></div>{l.photos.length>0&&<div className="gallery">{l.photos.map((p,i)=><img key={i} src={p} alt={'Terreno, foto '+(i+1)}/>)}</div>}<DetailGrid entries={[[l.condition==='Quitado'?'Preço anunciado':'Valor do ágio',cash(l.condition==='Quitado'?l.price:l.premium)],...(l.condition==='Ágio'?[['Saldo devedor',l.balance==null?'Não informado':cash(l.balance)],['Referência do saldo',brdate(l.balanceDate)],['Total estimado',price(l)==null?'Indisponível':cash(price(l))]]:[]),['Preço por m²',price(l)==null?'Indisponível':cash(price(l)/l.area)+(l.condition==='Ágio'?' (estimado)':'')],['Condição',l.condition],['Proprietário',l.owner],['Contato',l.contact],['Responsável',db.users.find(u=>u.id===l.brokerId)?.name],['Localização',l.address]]}/><div className="detail-note"><h3>Condições de pagamento</h3><div className="actions">{l.paymentOptions.map(x=><Badge key={x}>{x}</Badge>)}</div><p>{l.paymentTerms||'Não informadas.'}</p></div>{l.description&&<div className="detail-note"><h3>Descrição</h3><p>{l.description}</p></div>}{l.notes&&<div className="detail-note"><h3>Observações</h3><p>{l.notes}</p></div>}<h3 className="section-title">Linha do tempo</h3><form className="activity-form" onSubmit={async e=>{e.preventDefault();setError('');try{await mutate('land.activity',{id:l.id,content:activity},false);setActivity('');}catch(e){setError(e.message);}}}><textarea aria-label="Nova atividade" placeholder="Registre uma visita, proposta ou contato com o proprietário…" value={activity} onChange={e=>setActivity(e.target.value)} required/><button className="primary" disabled={busy}><Plus size={16}/>Adicionar atividade</button>{error&&<p className="error">{error}</p>}</form><Timeline items={l.history}/></div>;}
function ProductDetail({item,db,open}){const p=db.products.find(p=>p.id===item.id);return <div className="detail-content"><div className="detail-title"><div><h2>{p.name}</h2><p>{p.location}</p></div>{db.user.role==='Gestor'&&<button onClick={()=>open({type:'product',item:p})}><Pencil size={16}/>Editar</button>}</div>{p.photos.length>0&&<div className="gallery">{p.photos.map((x,i)=><img key={i} src={x} alt={'Produto, foto '+(i+1)}/>)}</div>}<p className="detail-description">{p.description}</p><div className="actions"><Badge>{p.active?'Ativo':'Inativo'}</Badge><Badge>{p.construction?'Construção liberada':'Não liberado'}</Badge>{p.launch&&<Badge>Lançamento</Badge>}</div><DetailGrid entries={[["Loteadora",db.developers.find(d=>d.id===p.developerId)?.name],['Comissão',p.percent+'%'],['Parcelas',p.installments],['Dia previsto de pagamento',p.payDay]]}/>{p.mapUrl&&<a className="link" href={p.mapUrl} target="_blank" rel="noreferrer">Abrir localização no mapa</a>}</div>;}
function SaleDetail({item,db,mutate,busy}){const s=db.sales.find(s=>s.id===item.id),[edit,setEdit]=useState(false),[receiving,setReceiving]=useState(null),[cancel,setCancel]=useState(false),[reason,setReason]=useState(''),[error,setError]=useState('');return <div className="detail-content"><div className="detail-title"><div><h2>{s.client}</h2><p>{s.productName} · Quadra {s.block} · Lote {s.lot}</p></div><Badge>{s.status}</Badge></div><div className="actions"><Badge>{s.contract}</Badge><Badge>{'Cliente: '+statusClient(s)}</Badge>{s.status!=='Cancelada'&&<button onClick={()=>setEdit(!edit)}><Pencil size={15}/>Atualizar contrato / pagamento</button>}</div><DetailGrid entries={[["Valor total do lote (VGV)",cash(s.value)],['Data da venda',brdate(s.date)],['Corretor',db.users.find(u=>u.id===s.brokerId)?.name],['Contato do cliente',s.contact],['Assinatura',brdate(s.signedAt)],['Pagamento inicial',cash(s.initial)],['Vencimento do cliente',brdate(s.initialDue)],['Pagamento efetivo',brdate(s.paidAt)]]}/>{edit&&<div className="inline-form"><FormShell initial={s} onSave={async v=>{await mutate('sale.update',v,false);setEdit(false);}} onCancel={()=>setEdit(false)} busy={busy}>{(v,set)=><><Select v={v} set={set} name="contract" label="Contrato" options={['Aguardando assinatura','Assinado']}/><Input v={v} set={set} name="signedAt" label="Data de assinatura" type="date" max={today} required={v.contract==='Assinado'}/><Input v={v} set={set} name="paidAt" label="Data do pagamento inicial" type="date" max={today}/><Select v={v} set={set} name="status" label="Situação da venda" options={['Em andamento','Concluída']}/><Textarea v={v} set={set} name="notes" label="Observações"/></>}</FormShell></div>}<div className="sale-commission-header"><div><h3>Comissão do corretor</h3><p>{s.rule.percent}% do valor total · {s.rule.installments} parcelas · dia {s.rule.payDay}</p></div><strong>{cash(total(s))}</strong></div>{s.status==='Cancelada'&&<p className="notice">Venda cancelada. Recebimentos anteriores preservados no histórico. O saldo não entra nas previsões do painel.</p>}<div className="table-scroll"><table><thead><tr><th>Parcela</th><th>Previsto</th><th>Vencimento</th><th>Situação</th><th>Recebido</th><th>Último recebimento</th>{db.user.role==='Gestor'&&<th/>}</tr></thead><tbody>{s.commissions.map(p=><tr key={p.id}><td>{p.number}/{s.rule.installments}</td><td>{cash(p.amount)}</td><td>{brdate(p.due)}</td><td><Badge>{statusParcel(p)}</Badge></td><td>{cash(p.received)}</td><td>{brdate(p.receivedAt)}</td>{db.user.role==='Gestor'&&<td>{s.status!=='Cancelada'&&statusParcel(p)!=='Paga'&&<button onClick={()=>setReceiving(p)}>Receber</button>}</td>}</tr>)}</tbody></table></div><div className="commission-footer"><span>Recebida: <strong>{cash(received(s))}</strong></span><span>Saldo: <strong>{cash(total(s)-received(s))}</strong></span></div>{receiving&&<div className="inline-form"><h3>Receber parcela {receiving.number}</h3><FormShell key={receiving.id} initial={{saleId:s.id,id:receiving.id,amount:Math.round((receiving.amount-receiving.received)*100)/100,receivedAt:today}} onSave={async v=>{await mutate('commission.receive',v,false);setReceiving(null);}} onCancel={()=>setReceiving(null)} busy={busy} submit="Confirmar recebimento">{(v,set)=><><Input v={v} set={set} name="amount" label="Valor recebido (R$)" type="number" min="0.01" max={receiving.amount-receiving.received} required/><Input v={v} set={set} name="receivedAt" label="Data de recebimento" type="date" max={today} required/></>}</FormShell></div>}{s.notes&&<div className="detail-note"><h3>Observações</h3><p>{s.notes}</p></div>}<h3 className="section-title">Histórico da venda</h3><Timeline items={s.history}/>{db.user.role==='Gestor'&&s.status!=='Cancelada'&&<div className="cancel-zone">{cancel?<form onSubmit={async e=>{e.preventDefault();setError('');try{await mutate('sale.cancel',{id:s.id,reason},false);setCancel(false);}catch(e){setError(e.message);}}}><p>Cancelar retira a venda do ranking e das previsões. Recebimentos já registrados serão mantidos.</p><Field label="Motivo do cancelamento"><textarea required value={reason} onChange={e=>setReason(e.target.value)}/></Field><div className="actions"><button type="button" onClick={()=>setCancel(false)}>Voltar</button><button className="danger" disabled={busy}>Confirmar cancelamento</button></div>{error&&<p className="error">{error}</p>}</form>:<button className="danger" onClick={()=>setCancel(true)}>Cancelar venda</button>}</div>}</div>;}
const landFields=[['neighborhood','Bairro'],['block','Quadra'],['lot','Lote'],['area','Área (m²)'],['condition','Condição'],['price','Valor total pedido'],['premium','Valor do ágio'],['balance','Saldo devedor'],['balanceDate','Data de referência do saldo'],['owner','Proprietário'],['contact','Contato'],['address','Localização'],['description','Descrição'],['notes','Observações'],['paymentTerms','Condições de pagamento'],['paymentOptions','Formas de pagamento'],['brokerId','Corretor responsável'],['availability','Disponibilidade']];
const numericFields=['area','price','premium','balance'];
const normalize=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
const keyLand=l=>[l.neighborhood,l.block,l.lot].map(normalize).join('|');
function localNumber(raw){if(raw===''||raw==null)return '';if(typeof raw==='number')return raw;let s=String(raw).replace(/R\$|\s/g,'');if(s.includes(','))s=s.replace(/\./g,'').replace(',','.');else if(/^\d{1,3}(\.\d{3})+$/.test(s))s=s.replace(/\./g,'');return Number(s);}
function importDate(raw){if(!raw)return '';if(raw instanceof Date)return raw.toISOString().slice(0,10);if(typeof raw==='number')return new Date(Date.UTC(1899,11,30)+raw*864e5).toISOString().slice(0,10);let s=String(raw).trim();if(/^\d{2}\/\d{2}\/\d{4}$/.test(s))return s.split('/').reverse().join('-');return s;}
function mappedRow(raw,mapping,db){const l={};for(const [field]of landFields){const rawVal=mapping[field]!==undefined&&mapping[field]!==''?raw[+mapping[field]]:'';l[field]=numericFields.includes(field)?localNumber(rawVal):field==='balanceDate'?importDate(rawVal):String(rawVal??'').trim();}l.condition=normalize(l.condition)==='agio'?'Ágio':normalize(l.condition)==='quitado'?'Quitado':l.condition;l.availability=['Disponível','Reservado','Vendido','Inativo'].find(x=>normalize(x)===normalize(l.availability))||l.availability||'Disponível';l.brokerId=db.users.find(u=>u.id===l.brokerId||normalize(u.name)===normalize(l.brokerId))?.id||db.user.id;l.paymentOptions=l.paymentOptions.split(/[,;]/).map(x=>['Entrada','Parcelamento','Financiamento','Permuta'].find(y=>normalize(x)===normalize(y))).filter(Boolean);return l;}
function importErrors(l){const errors=[];for(const [k,label]of landFields.filter(([k])=>['neighborhood','block','lot','area','condition','owner','contact'].includes(k)))if(l[k]===''||l[k]==null)errors.push(label+' obrigatório');for(const k of numericFields)if(l[k]!==''&&l[k]!=null&&(!Number.isFinite(l[k])||l[k]<0))errors.push(k+': número inválido');if(!(l.area>0))errors.push('Área deve ser positiva');if(!['Quitado','Ágio'].includes(l.condition))errors.push('Condição deve ser Quitado ou Ágio');if(l.condition==='Quitado'&&!(l.price>0))errors.push('Informe o valor total pedido');if(l.condition==='Ágio'&&(l.premium===''||!Number.isFinite(l.premium)))errors.push('Informe o ágio');if(l.condition==='Ágio'&&l.balance!==''&&l.balance!=null&&!l.balanceDate)errors.push('Informe a data do saldo');if(l.balanceDate&&(!/^\d{4}-\d{2}-\d{2}$/.test(l.balanceDate)||Number.isNaN(Date.parse(l.balanceDate))||new Date(l.balanceDate).toISOString().slice(0,10)!==l.balanceDate))errors.push('Data do saldo inválida');return errors;}
async function excel(){const mod=await import('exceljs');return mod.default||mod;}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function downloadJSON(lands){downloadBlob(new Blob([JSON.stringify({format:'lotea-terrenos',version:1,exportedAt:new Date().toISOString(),lands},null,2)],{type:'application/json'}),'lotea-backup-terrenos-'+today+'.json');}
async function exportLands(lands,db){const Excel=await excel(),wb=new Excel.Workbook();wb.creator='Lotea';const sh=wb.addWorksheet('Terrenos');sh.columns=landFields.map(([key,header])=>({key,header,width:['description','notes','paymentTerms','address'].includes(key)?40:24}));for(const l of lands)sh.addRow({...l,brokerId:db.users.find(u=>u.id===l.brokerId)?.name||l.brokerId,paymentOptions:l.paymentOptions.join('; ')});sh.getRow(1).font={bold:true,color:{argb:'FFFFFFFF'}};sh.getRow(1).fill={type:'pattern',pattern:'solid',fgColor:{argb:'FF102D3D'}};sh.views=[{state:'frozen',ySplit:1}];sh.autoFilter={from:'A1',to:'R1'};for(const key of numericFields)sh.getColumn(key).numFmt='#,##0.00';const hist=wb.addWorksheet('Histórico');hist.columns=[{header:'Bairro',key:'neighborhood',width:25},{header:'Quadra',key:'block'},{header:'Lote',key:'lot'},{header:'Autor',key:'author',width:25},{header:'Data e hora',key:'at',width:28},{header:'Atividade',key:'action',width:28},{header:'Conteúdo',key:'details',width:80}];for(const l of lands)for(const h of l.history)hist.addRow({...h,neighborhood:l.neighborhood,block:l.block,lot:l.lot});downloadBlob(new Blob([await wb.xlsx.writeBuffer()],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),'lotea-terrenos-'+today+'.xlsx');}
function ImportForm({db,mutate,close,busy}){const [sheets,setSheets]=useState([]),[sheet,setSheet]=useState(0),[mapping,setMapping]=useState({}),[stage,setStage]=useState(0),[strategy,setStrategy]=useState('skip'),[error,setError]=useState(''),[reading,setReading]=useState(false),[result,setResult]=useState(null);const rows=sheets[sheet]?.rows||[],headers=rows[0]||[];const source=rows.slice(1).filter(r=>r.some(v=>v!==''&&v!=null));const mapped=source.map(r=>mappedRow(r,mapping,db)),seen=new Set(db.lands.map(keyLand)),checks=mapped.map(l=>{const duplicate=seen.has(keyLand(l));seen.add(keyLand(l));return {errors:importErrors(l),duplicate};});function autoMap(rows){const m={};for(const [k,label]of landFields){const i=(rows[0]||[]).findIndex(h=>normalize(h)===normalize(label)||normalize(h)===normalize(k));if(i>=0)m[k]=String(i);}setMapping(m);}
return <div className="import-content"><div className="import-steps"><span className={stage===0?'active':''}>1. Planilha e colunas</span><ChevronRight size={16}/><span className={stage===1?'active':''}>2. Prévia e confirmação</span><ChevronRight size={16}/><span className={stage===2?'active':''}>3. Resultado</span></div>{stage===0&&<><label className="upload-zone"><FileSpreadsheet size={32}/><strong>{reading?'Lendo planilha…':'Selecione uma planilha Excel'}</strong><span>Formato .xlsx · até 5 MB · até 2.000 linhas por importação</span><input type="file" accept=".xlsx" disabled={reading} onChange={async e=>{setError('');setReading(true);try{const f=e.target.files[0];if(!f)return;if(f.size>5e6)throw Error('O arquivo deve ter até 5 MB.');const Excel=await excel(),wb=new Excel.Workbook();await wb.xlsx.load(await f.arrayBuffer());const ss=wb.worksheets.map(s=>({name:s.name,rows:s.getSheetValues().slice(1).map(row=>Array.from({length:s.columnCount},(_,i)=>{const v=row?.[i+1];if(v&&typeof v==='object'&&!(v instanceof Date))return v.result??v.text??v.richText?.map(r=>r.text).join('')??'';return v??'';}))})).filter(s=>s.rows.length);if(!ss.length)throw Error('A planilha está vazia.');if(ss.some(s=>s.rows.length>2001))throw Error('Divida a planilha em arquivos com até 2.000 registros.');setSheets(ss);setSheet(0);autoMap(ss[0].rows);}catch(e){setError('Não foi possível ler o arquivo. '+e.message);}finally{setReading(false);}}}/></label><p className="form-help">A primeira linha deve conter os nomes das colunas. Para arquivos antigos .xls, salve uma cópia como .xlsx no Excel.</p>{sheets.length>0&&<><Field label="Aba da planilha"><select value={sheet} onChange={e=>{setSheet(+e.target.value);autoMap(sheets[+e.target.value].rows);}}>{sheets.map((s,i)=><option key={i} value={i}>{s.name}</option>)}</select></Field><h3 className="section-title">Associe as colunas</h3><div className="mapping-grid">{landFields.map(([key,label])=><Field key={key} label={label}><select aria-label={'Coluna '+label} value={mapping[key]??''} onChange={e=>setMapping({...mapping,[key]:e.target.value})}><option value="">Não importar</option>{headers.map((h,i)=><option key={i} value={String(i)}>{String(h)||'Coluna '+(i+1)}</option>)}</select></Field>)}</div></>}</>}{stage===1&&<><div className="notice">{mapped.length} registros · {checks.filter(c=>c.duplicate).length} possíveis duplicidades · {checks.filter(c=>c.errors.length).length} registros precisam de correção</div><Field label="Como tratar bairro, quadra e lote já existentes?"><select value={strategy} onChange={e=>setStrategy(e.target.value)}><option value="skip">Ignorar duplicados e manter os dados atuais</option><option value="update">Atualizar duplicados com os dados desta planilha</option></select></Field>{strategy==='update'&&<p className="error">Ao confirmar, os campos dos terrenos duplicados serão substituídos pelos dados mapeados. Campos não mapeados ficarão vazios. O histórico anterior será preservado.</p>}<div className="table-scroll import-preview"><table><thead><tr><th>Linha</th><th>Bairro / quadra / lote</th><th>Área</th><th>Valor</th><th>Validação</th></tr></thead><tbody>{mapped.map((l,i)=><tr key={i}><td>{i+2}</td><td>{l.neighborhood}<small>Q{l.block} · L{l.lot}</small></td><td>{l.area} m²</td><td>{cash(l.condition==='Ágio'?l.premium:l.price)}</td><td>{checks[i].errors.length?<span className="red-text">{checks[i].errors.join('; ')}</span>:<Badge>{checks[i].duplicate?'Duplicado':'Pronto'}</Badge>}</td></tr>)}</tbody></table></div><p className="form-help">Registros com erros serão rejeitados, com indicação da linha para correção. A validação será repetida no servidor.</p></>}{stage===2&&result&&<><div className="import-success"><CheckCircle2 size={38}/><h3>Importação concluída</h3><p>{result.imported} importados · {result.updated} atualizados · {result.skipped} duplicados ignorados</p></div>{result.errors.length>0&&<div className="error"><strong>{result.errors.length} registros precisam de correção</strong>{result.errors.map(e=><p key={e.row}>Linha {e.row}: {e.message}</p>)}</div>}</>}{error&&<p className="error">{error}</p>}<div className="form-footer">{stage===0?<><button onClick={close}>Cancelar</button><button className="primary" disabled={!source.length||reading} onClick={()=>setStage(1)}>Visualizar prévia</button></>:stage===1?<><button onClick={()=>setStage(0)}>Voltar ao mapeamento</button><button className="primary" disabled={busy} onClick={async()=>{setError('');try{const r=await mutate('land.import',{rows:mapped,strategy},false);setResult(r.importResult);setStage(2);}catch(e){setError(e.message);}}}>{busy?'Importando…':'Confirmar importação'}</button></>:<button className="primary" onClick={close}>Concluir</button>}</div></div>;}
function ModalBody({modal,db,mutate,open,close,busy}){const props={item:modal.item,db,mutate,open,close,busy};switch(modal.type){case'land':return <LandForm {...props}/>;case'product':return <ProductForm {...props}/>;case'sale':return <SaleForm {...props}/>;case'user':return <UserForm {...props}/>;case'developer':return <FormShell initial={modal.item||{name:'',contact:'',percent:3,installments:3,payDay:20}} onSave={v=>mutate('developer.save',v)} onCancel={close} busy={busy}>{(v,set)=><DeveloperFields v={v} set={set}/>}</FormShell>;case'landDetail':return <LandDetail {...props}/>;case'productDetail':return <ProductDetail {...props}/>;case'saleDetail':return <SaleDetail {...props}/>;case'import':return <ImportForm {...props}/>;case'alerts':return <div className="detail-content">{modal.sales.filter(s=>statusClient(s)==='Atrasado'||s.commissions.some(p=>statusParcel(p)==='Atrasada')).map(s=><button className="alert-item" key={s.id} onClick={()=>open({type:'saleDetail',item:s})}><div><strong>{s.client}</strong><small>{s.productName}</small><p>{statusClient(s)==='Atrasado'?'Pagamento inicial atrasado. ':''}{s.commissions.filter(p=>statusParcel(p)==='Atrasada').length} parcelas de comissão atrasadas.</p></div><ChevronRight size={18}/></button>)}</div>;default:return null;}}
